import{_ as e,C as i,c as n,o as r,j as t,b as a,a0 as l,a as u,w as s,G as h,a1 as o}from"./chunks/framework.DKRgXLPU.js";const d=JSON.parse('{"title":"Aufbau deiner Pre-Spuck-Routine","description":"","frontmatter":{},"headers":[],"relativePath":"de/education/mental-strength/pre-shot-routine.md","filePath":"de/education/mental-strength/pre-shot-routine.md"}');const g=e({name:"de/education/mental-strength/pre-shot-routine.md"},[["render",function(e,d,g,c,f,b){const m=i("Mermaid");return r(),n("div",null,[d[1]||(d[1]=t("h1",{id:"aufbau-deiner-pre-spuck-routine",tabindex:"-1"},[u("Aufbau deiner Pre-Spuck-Routine "),t("a",{class:"header-anchor",href:"#aufbau-deiner-pre-spuck-routine","aria-label":'Permalink to "Aufbau deiner Pre-Spuck-Routine"'},"​")],-1)),d[2]||(d[2]=t("p",null,"Deine Vorbereitungsroutine vor dem Wurf ist eines der wirkungsvollsten Instrumente für deine mentale Stärke. Es handelt sich um eine festgelegte Abfolge von Handlungen, die dich auf jeden Wurf vorbereitet und deine Bestleistung ermöglicht.",-1)),d[3]||(d[3]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"Die große Idee"),t("p",null,[t("strong",null,"Deine Routine ist der Schlüssel zum Flow."),u(" Eine konsequente Vorbereitungsroutine signalisiert deinem Gehirn: „Jetzt geht’s los.“ Durch Wiederholung wird sie zum automatischen Auslöser für Höchstleistungen.")])],-1)),(r(),a(o,null,{default:s(()=>[h(m,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BRoutine%20beginnen%5D%20--%3E%20B%5BDas%20Gehirn%20erkennt%20das%20Muster%5D%0A%20%20%20%20B%20--%3E%20C%5BAutomatischer%20Zustandswechsel%5D%0A%20%20%20%20C%20--%3E%20D%5BAusf%C3%BChrungsmodus%5D%0A%20%20%20%20D%20--%3E%20E%5BSpitzenleistung%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e8f5e9%0A%20%20%20%20style%20D%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:s(()=>[...d[0]||(d[0]=[u(" Loading... ",-1)])]),_:1})),d[4]||(d[4]=l('<h2 id="warum-routinen-funktionieren" tabindex="-1">Warum Routinen funktionieren <a class="header-anchor" href="#warum-routinen-funktionieren" aria-label="Permalink to &quot;Warum Routinen funktionieren&quot;">​</a></h2><h3 id="bestandigkeit-schafft-vertrauen" tabindex="-1">Beständigkeit schafft Vertrauen. <a class="header-anchor" href="#bestandigkeit-schafft-vertrauen" aria-label="Permalink to &quot;Beständigkeit schafft Vertrauen.&quot;">​</a></h3><p>Wenn man immer dasselbe tut, eliminiert man Variablen. Der Körper weiß, was kommt. Das erzeugt ein Gefühl von Kontrolle und Vertrautheit, selbst in ungewohnten Situationen.</p><h3 id="routinen-losen-zustande-aus" tabindex="-1">Routinen lösen Zustände aus <a class="header-anchor" href="#routinen-losen-zustande-aus" aria-label="Permalink to &quot;Routinen lösen Zustände aus&quot;">​</a></h3><p>Durch Wiederholung verknüpft sich Ihre Routine mit Ihrem Leistungszustand. Der Beginn der Routine leitet automatisch den mentalen Wechsel in den Ausführungsmodus ein.</p><h3 id="routinen-blockieren-ablenkungen" tabindex="-1">Routinen blockieren Ablenkungen <a class="header-anchor" href="#routinen-blockieren-ablenkungen" aria-label="Permalink to &quot;Routinen blockieren Ablenkungen&quot;">​</a></h3><p>Eine feste Routine gibt dem Geist etwas, worauf er sich konzentrieren kann. Es bleibt kein Raum für Sorgen um die Punktzahl, das Publikum oder was passieren könnte.</p><h3 id="routinen-regulieren-die-erregung" tabindex="-1">Routinen regulieren die Erregung <a class="header-anchor" href="#routinen-regulieren-die-erregung" aria-label="Permalink to &quot;Routinen regulieren die Erregung&quot;">​</a></h3><p>Eine gut durchdachte Routine hilft dabei, Ihr Energieniveau zu regulieren – sie beruhigt Sie, wenn Sie zu aufgedreht sind, und hilft Ihnen, sich zu konzentrieren, wenn Sie schlapp sind.</p><h2 id="elemente-einer-effektiven-routine" tabindex="-1">Elemente einer effektiven Routine <a class="header-anchor" href="#elemente-einer-effektiven-routine" aria-label="Permalink to &quot;Elemente einer effektiven Routine&quot;">​</a></h2><h3 id="phase-1-beurteilung-außerhalb-des-kreises" tabindex="-1">Phase 1: Beurteilung (Außerhalb des Kreises) <a class="header-anchor" href="#phase-1-beurteilung-außerhalb-des-kreises" aria-label="Permalink to &quot;Phase 1: Beurteilung (Außerhalb des Kreises)&quot;">​</a></h3><p>Bevor Sie eingreifen, sammeln Sie Informationen:</p><ul><li>Lesen Sie das Gelände (Hänge, Hindernisse, Oberfläche).</li><li>Beurteilen Sie die Situation (Punktzahl, Boule-Positionen)</li><li>Wählen Sie Ihr Ziel und Ihren Landeplatz.</li><li>Wähle die Wurfart (Punktwurf, Schusswurf, Lobwurf, Rollwurf).</li></ul><p><strong>Hier findet das Denken statt.</strong> Nehmen Sie sich hier Zeit.</p><h3 id="phase-2-ubergang-eintritt-in-den-kreis" tabindex="-1">Phase 2: Übergang (Eintritt in den Kreis) <a class="header-anchor" href="#phase-2-ubergang-eintritt-in-den-kreis" aria-label="Permalink to &quot;Phase 2: Übergang (Eintritt in den Kreis)&quot;">​</a></h3><p>Der Übergang vom Denken zum Handeln:</p><ul><li>Körperliche Handlung (gleichmäßig in den Kreis treten)</li><li>Mentaler Hinweis (ein Wort oder eine Phrase, die den „Ausführungsmodus“ signalisiert)</li><li>Atem (ein bewusster Atemzug zur Zentrierung)</li></ul><p><strong>Dies ist der Schalter.</strong> Die Analyse endet hier.</p><h3 id="phase-3-aufbau-im-kreis" tabindex="-1">Phase 3: Aufbau (Im Kreis) <a class="header-anchor" href="#phase-3-aufbau-im-kreis" aria-label="Permalink to &quot;Phase 3: Aufbau (Im Kreis)&quot;">​</a></h3><p>Bereite deinen Körper vor:</p><ul><li>Konsequente Haltung (immer gleich)</li><li>Griffprüfung (die Kugel fühlen)</li><li>Ausrichtung auf das Ziel</li><li>Physischer Auslöser (eine kleine Bewegung von Ihnen)</li></ul><h3 id="phase-4-visualisierung-kurzfassung" tabindex="-1">Phase 4: Visualisierung (Kurzfassung) <a class="header-anchor" href="#phase-4-visualisierung-kurzfassung" aria-label="Permalink to &quot;Phase 4: Visualisierung (Kurzfassung)&quot;">​</a></h3><p>Sieh dir den Wurf an, bevor du ihn ausführst:</p><ul><li>Stell dir die Flugbahn des Balls vor (maximal 2-3 Sekunden).</li><li>Spüre den erfolgreichen Wurf</li><li>Stellen Sie eine visuelle Verbindung zu Ihrem Ziel her.</li></ul><h3 id="phase-5-ausfuhrung" tabindex="-1">Phase 5: Ausführung <a class="header-anchor" href="#phase-5-ausfuhrung" aria-label="Permalink to &quot;Phase 5: Ausführung&quot;">​</a></h3><p>Führe den Wurf aus:</p><ul><li>Externer Fokus (nur Ziel)</li><li>Vertraue deinem Körper</li><li>Ohne Zögern freigeben</li><li>Setzen Sie es natürlich fort</li></ul><h2 id="aufbau-ihrer-personlichen-routine" tabindex="-1">Aufbau Ihrer persönlichen Routine <a class="header-anchor" href="#aufbau-ihrer-personlichen-routine" aria-label="Permalink to &quot;Aufbau Ihrer persönlichen Routine&quot;">​</a></h2><h3 id="schritt-1-beobachten-sie-was-sie-bereits-tun" tabindex="-1">Schritt 1: Beobachten Sie, was Sie bereits tun <a class="header-anchor" href="#schritt-1-beobachten-sie-was-sie-bereits-tun" aria-label="Permalink to &quot;Schritt 1: Beobachten Sie, was Sie bereits tun&quot;">​</a></h3><p>Sie haben wahrscheinlich bereits eine gewisse Routine. Hinweis:</p><ul><li>Was machst du vor guten Würfen?</li><li>Was fühlt sich für dich natürlich an?</li><li>Was hilft Ihnen, sich zu konzentrieren?</li></ul><h3 id="schritt-2-gestalte-deine-routine" tabindex="-1">Schritt 2: Gestalte deine Routine <a class="header-anchor" href="#schritt-2-gestalte-deine-routine" aria-label="Permalink to &quot;Schritt 2: Gestalte deine Routine&quot;">​</a></h3><p>Erstellen Sie eine Sequenz, die Folgendes enthält:</p><ul><li>[ ] Bewertungsphase</li><li>[ ] Klarer Übergangsmoment</li><li>[ ] Einheitliche physische Einrichtung</li><li>[ ] Kurze Visualisierung</li><li>[ ] Ausführungsauslöser</li></ul><h3 id="schritt-3-schreiben-sie-es-auf" tabindex="-1">Schritt 3: Schreiben Sie es auf <a class="header-anchor" href="#schritt-3-schreiben-sie-es-auf" aria-label="Permalink to &quot;Schritt 3: Schreiben Sie es auf&quot;">​</a></h3><p>Seien Sie konkret. Beispiel:</p><ol><li><strong>Beurteilen:</strong> Gelände analysieren, Landeplatz auswählen</li><li><strong>Übergang:</strong> Treten Sie mit dem linken Fuß zuerst in den Kreis und sagen Sie „Vertrauen“.</li><li><strong>Vorbereitung:</strong> Füße schulterbreit, Griffkraft prüfen, Schultern ausrichten</li><li><strong>Visualisieren:</strong> Sehen Sie den Weg, spüren Sie die Erleichterung.</li><li><strong>Ausführung:</strong> Ziel im Blick behalten, werfen</li></ol><h3 id="schritt-4-uben-sie-regelmaßig" tabindex="-1">Schritt 4: Üben Sie regelmäßig <a class="header-anchor" href="#schritt-4-uben-sie-regelmaßig" aria-label="Permalink to &quot;Schritt 4: Üben Sie regelmäßig&quot;">​</a></h3><p>Wende deine Routine bei JEDEM Wurf im Training an:</p><ul><li>Einfache Würfe</li><li>Schwierige Würfe</li><li>Wenn du müde bist</li><li>Wenn du frisch bist</li></ul><p>Die Routine muss zur Gewohnheit werden.</p><h3 id="schritt-5-im-laufe-der-zeit-verfeinern" tabindex="-1">Schritt 5: Im Laufe der Zeit verfeinern <a class="header-anchor" href="#schritt-5-im-laufe-der-zeit-verfeinern" aria-label="Permalink to &quot;Schritt 5: Im Laufe der Zeit verfeinern&quot;">​</a></h3><p>Deine Routine wird sich weiterentwickeln. Beobachte, was funktioniert, und passe sie an. Ändere sie aber nicht während des Wettkampfs – nur zwischen den Disziplinen.</p><h2 id="routine-zeitmessung" tabindex="-1">Routine-Zeitmessung <a class="header-anchor" href="#routine-zeitmessung" aria-label="Permalink to &quot;Routine-Zeitmessung&quot;">​</a></h2><p>Ihre Routine sollte einen gleichbleibenden Zeitaufwand erfordern:</p><ul><li>Zu schnell: Sie sind in Eile und nicht ausreichend vorbereitet.</li><li>Zu langsam: Du denkst zu viel nach und verlierst den Fluss.</li><li>Genau richtig: Genügend Zeit zur Vorbereitung, aber nicht so viel, dass man zu viel nachdenkt.</li></ul><p><strong>Typischer Zeitablauf:</strong></p><ul><li>Einschätzung: 5-10 Sekunden</li><li>Übergang + Vorbereitung: 3-5 Sekunden</li><li>Visualisierung + Ausführung: 3-5 Sekunden</li><li><strong>Gesamt: 10-20 Sekunden</strong></li></ul><h2 id="haufige-routinefehler" tabindex="-1">Häufige Routinefehler <a class="header-anchor" href="#haufige-routinefehler" aria-label="Permalink to &quot;Häufige Routinefehler&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fehler</th><th>Problem</th><th>Lösung</th></tr></thead><tbody><tr><td>Seilspringen in der Praxis</td><td>Routinen sind nicht automatisch</td><td>Nutze es bei jedem einzelnen Wurf.</td></tr><tr><td>Zu kompliziert</td><td>Unter Druck schwer zu erinnern.</td><td>Auf das Wesentliche reduzieren</td></tr><tr><td>Denken während der Ausführung</td><td>Stört die automatische Leistung</td><td>Klarer Übergangspunkt</td></tr><tr><td>Uneinheitliche Zeitmessung</td><td>Schafft Unsicherheit</td><td>Üben Sie in gleichmäßigem Tempo</td></tr><tr><td>Wechsel mitten im Wettbewerb</td><td>Weckt Zweifel</td><td>Bleib bei dem, was du kennst.</td></tr></tbody></table><h2 id="routinemaßige-fehlerbehebung" tabindex="-1">Routinemäßige Fehlerbehebung <a class="header-anchor" href="#routinemaßige-fehlerbehebung" aria-label="Permalink to &quot;Routinemäßige Fehlerbehebung&quot;">​</a></h2><p><strong>Wenn Sie es eilig haben:</strong></p><ul><li>Füge beim Übergang einen Atemzug hinzu.</li><li>Verlangsamen Sie Ihre Setup-Bewegungen</li><li>Pause vor der Visualisierung</li></ul><p><strong>Wenn Sie zu viel nachdenken:</strong></p><ul><li>Verkürzen Sie die Routine</li><li>Verwenden Sie ein stärkeres Übergangssignal.</li><li>Konzentriere dich mehr auf das Äußere.</li></ul><p><strong>Wenn Sie inkonsequent sind:</strong></p><ul><li>Filmen Sie sich selbst, um zu überprüfen</li><li>Übe die Übung ohne zu werfen.</li><li>Holen Sie sich Feedback von einem Partner</li></ul><h2 id="beispielroutinen" tabindex="-1">Beispielroutinen <a class="header-anchor" href="#beispielroutinen" aria-label="Permalink to &quot;Beispielroutinen&quot;">​</a></h2><h3 id="einfache-routine" tabindex="-1">Einfache Routine <a class="header-anchor" href="#einfache-routine" aria-label="Permalink to &quot;Einfache Routine&quot;">​</a></h3><ol><li>Ziel auswählen</li><li>Treten Sie ein, atmen Sie durch.</li><li>Greifen, ausrichten</li><li>Siehst du es, wirf es weg!</li></ol><h3 id="detaillierter-ablauf" tabindex="-1">Detaillierter Ablauf <a class="header-anchor" href="#detaillierter-ablauf" aria-label="Permalink to &quot;Detaillierter Ablauf&quot;">​</a></h3><ol><li>Gelände einschätzen, Landeplatz auswählen</li><li>Setzen Sie zuerst den linken Fuß ein.</li><li>innerlich „glatt“ sagen</li><li>Ein Atemzug, die Schultern sinken.</li><li>Füße positionieren, Griff prüfen</li><li>Schultern zum Ziel ausrichten</li><li>Den Pfad ansehen (2 Sekunden)</li><li>Blick fixiert auf das Ziel</li><li>Werfen</li></ol><h2 id="wichtigste-erkenntnis" tabindex="-1">Wichtigste Erkenntnis <a class="header-anchor" href="#wichtigste-erkenntnis" aria-label="Permalink to &quot;Wichtigste Erkenntnis&quot;">​</a></h2><blockquote><p>Deine Routine ist dein Anker. Im Chaos ist sie deine Konstante.</p></blockquote><p>Baue es sorgfältig. Übe es immer wieder. Vertraue ihm vollkommen.</p>',65))])}]]);export{d as __pageData,g as default};
